import urllib.request
for url in ['https://developers.openai.com/api/reference/resources/responses/methods/create','https://developers.openai.com/api/docs/guides/your-data']:
    try:
        with urllib.request.urlopen(url, timeout=30) as r:
            s=r.read().decode()
        from html import unescape
        import re
        s=unescape(re.sub('<["'^>]+>'"', ' ', s))
        print(url)
        for term in ['store', 'output_text', 'abuse monitoring']:
            m=re.search(term,s,re.I)
            if m: print(s[max(0,m.start()-200):m.start()+700])
    except Exception as e: print(type(e).__name__)
PY"

