/bin/bash -lc "python -B - <<'PY'
import io, json, urllib.error, urllib.request
from unittest.mock import Mock
from openai_client import OpenAIClient, OpenAIError, _NoRedirects
client = OpenAIClient('test-key')
def fake(result):
    client._opener = Mock()
    client._opener.open.return_value = io.BytesIO(json.dumps(result).encode())
fake({'status':'completed','output':[{'type':'reasoning'}, {'type':'message','content':[{'type':'output_text','text':'Hello'}, {'type':'output_text','text':' world'}]}]})
assert client.respond('private prompt',model='test-model') == 'Hello world'
req = client._opener.open.call_args.args[0]
assert json.loads(req.data) == {'model':'test-model','input':'private prompt','store':False}
assert req.full_url == 'https://api.openai.com/v1/responses'
for result in [{'status':'incomplete'}, {'status':'completed','output':[]}, {'status':'completed','output':[{'type':'message','content':[{'type':'refusal','refusal':'private'}]}]}]:
    fake(result)
    try: client.respond('private prompt',model='test-model')
    except OpenAIError as e: assert 'private' not in str(e)
    else: raise AssertionError('expected failure')
client._opener.open.side_effect = urllib.error.HTTPError(req.full_url, 429, 'private', {}, io.BytesIO(b'private'))
try: client.respond('private prompt',model='test-model')
except OpenAIError as e:
    assert e.status_code == 429 and 'private' not in str(e)
else: raise AssertionError('expected HTTP failure')
assert _NoRedirects().redirect_request(req,None,302,'',{},'https://example.com') is None
assert 'test-key' not in repr(client)
print('Offline checks passed: payload, text extraction, incomplete/refusal handling, sanitized HTTP errors, redirect blocking.')
PY"

